    special = {color for color, count in counts.items() if count < total * 0.15}
    rows = [r for r in range(h) if any(grid[r][c] in special for c in range(w))]
    cols = [c for c in range(w) if any(grid[r][c] in special for r in range(h))]
    base = counts.most_common(1)[0][0]

